def max_window_sum(arr: list, k: int) -> int:
    """Largest sum of any k consecutive elements (sliding window)."""
    if k <= 0 or k > len(arr):
        return 0
    window = sum(arr[:k])
    best = window
    for i in range(k, len(arr)):
        window += arr[i] - arr[i - k]
        if window > best:
            best = window
    return best

print(max_window_sum([2, 1, 5, 1, 3, 2], 3))
